def legacy_receipts(apps, schema_editor):
    """Eski (qutiga bitta) cheklar 1-chek: barcha ta'mirdan qaytishlardagi 1-sort shu chekniki; ta'mir tugagan bo'lsa
    chek yopilgan. Eski TAMIR skanlari shu chekka bog'lanadi."""
    RepairReceipt = apps.get_model('production', 'RepairReceipt')
    Log = apps.get_model('production', 'BoxQualityInspectionLog')
    PackingScan = apps.get_model('production', 'PackingScan')
    for receipt in RepairReceipt.objects.select_related('box'):
        returns = Log.objects.filter(box_id=receipt.box_id, action_type='REPAIR_RETURN')
        receipt.first_sort_qty = returns.aggregate(s=Sum('first_sort_qty'))['s'] or 0
        last = returns.order_by('-created_at').first()
        if last and not receipt.box.controlled_repair_qty:
            receipt.returned_log, receipt.returned_at = last, last.created_at
        receipt.save(update_fields=['first_sort_qty', 'returned_log', 'returned_at'])
        PackingScan.objects.filter(box_id=receipt.box_id, source='TAMIR', repair_receipt__isnull=True).update(
            repair_receipt=receipt)



